/// Look up a bundled Lucide icon by its kebab-case name, e.g. `"circle-check"`.
pub fn by_name(name: &str) -> Option<IconData> {
    ALL.binary_search_by(|(k, _)| k.cmp(&name)).ok().map(|i| ALL[i].1)
}
